import os
import json
import asyncio
import aiohttp

TRANSPILE_SYSTEM_PROMPT = """You are a strict Python→zig transpiler. You will receive a complete Python file as input. A zig fájlnak önmagában külső fájlok nélkül is működnie kell You must return the equivalent zig code. soha semmi egyszerusitett mock placeholder dummy szimulalt fake szart nem engedelyezek csak a teljes fajl teljes roviditetlen production ready kód CRITICAL RULES (DO NOT BREAK THEM): 1. Output ONLY zig code. 2. NO comments at all. Do not keep original comments, do not add new ones. 3. NO explanations, NO summaries, NO notes. 4. NO placeholders, NO "...rest of code", NO "to be implemented". 5. Do not skip or shorten ANY part. Translate EVERY line. 6. The output must be complete, runnable zig code with nothing missing. a teljes kódot küldöd. minden egyes karaktert leírsz, nem rövidítesz. minden hibát kijavítasz. egy fájl marad. ne írj semmi mást csak a teljes kódot es kommentek nem lehetnek benne! soha semmi egyszerusitett mock placeholder dummy szimulalt fake szart nem engedelyezek es teljes fájl roviditetlen production ready kód"""

CONCURRENCY = 10
MAX_RETRIES = 3
BASE_DELAY = 2

rate_limit_lock = asyncio.Lock()
last_rate_limit_time = [0]


def normalize_messages(messages):
    normalized = []
    for message in messages:
        role = str(message.get("role", "user")).strip() or "user"
        content = message.get("content", "")
        if isinstance(content, str):
            normalized.append({
                "role": role,
                "content": [{
                    "type": "text",
                    "text": content
                }]
            })
        elif isinstance(content, list):
            parts = []
            for item in content:
                if isinstance(
                        item,
                        dict) and item.get("type") == "text" and isinstance(
                            item.get("text"), str):
                    parts.append({"type": "text", "text": item["text"]})
                elif isinstance(item, str):
                    parts.append({"type": "text", "text": item})
            if not parts:
                parts.append({"type": "text", "text": ""})
            normalized.append({"role": role, "content": parts})
        else:
            normalized.append({
                "role":
                role,
                "content": [{
                    "type": "text",
                    "text": str(content)
                }]
            })
    return normalized


async def invoke_bedrock_async(session,
                               messages,
                               system=None,
                               max_tokens=64000,
                               temperature=0.0,
                               region=None,
                               model_id=None,
                               api_key=None):
    if not api_key:
        return {
            "ok": False,
            "error": {
                "message": "Missing AWS_BEARER_TOKEN_BEDROCK"
            }
        }
    if not region:
        region = "us-east-1"
    if not model_id:
        model_id = "global.anthropic.claude-opus-4-5-20251101-v1:0"

    url = f""

    body = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": int(max_tokens),
        "messages": normalize_messages(messages)
    }
    if system:
        body["system"] = system
    if temperature is not None:
        body["temperature"] = float(temperature)

    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json",
        "Authorization": f"Bearer {api_key}",
        "x-amz-bedrock-api-version": "2023-10-01"
    }

    for attempt in range(MAX_RETRIES):
        try:
            async with session.post(
                    url,
                    json=body,
                    headers=headers,
                    timeout=aiohttp.ClientTimeout(total=600)) as response:
                status = response.status
                raw_bytes = await response.read()

                if status == 429 or "Too many requests" in raw_bytes.decode(
                        "utf-8", errors="ignore"):
                    async with rate_limit_lock:
                        import time
                        now = time.time()
                        if now - last_rate_limit_time[0] > 1:
                            last_rate_limit_time[0] = now
                            delay = BASE_DELAY * (attempt + 1)
                            await asyncio.sleep(delay)
                    continue

                if status >= 500:
                    await asyncio.sleep(BASE_DELAY)
                    continue

                if status != 200:
                    try:
                        error_body = json.loads(raw_bytes.decode("utf-8"))
                    except:
                        error_body = {
                            "message": raw_bytes.decode("utf-8",
                                                        errors="ignore")
                        }
                    return {"ok": False, "status": status, "error": error_body}

                try:
                    parsed = json.loads(raw_bytes.decode("utf-8"))
                    return {"ok": True, "data": parsed}
                except:
                    return {
                        "ok": True,
                        "data": {
                            "raw": raw_bytes.decode("utf-8", errors="ignore")
                        }
                    }
        except asyncio.TimeoutError:
            if attempt < MAX_RETRIES - 1:
                await asyncio.sleep(BASE_DELAY)
                continue
            return {"ok": False, "error": {"message": "Timeout"}}
        except Exception as e:
            if attempt < MAX_RETRIES - 1:
                await asyncio.sleep(BASE_DELAY)
                continue
            return {"ok": False, "error": {"message": str(e)}}

    return {"ok": False, "error": {"message": "Max retries exceeded"}}


def extract_zig_code(response_text):
    if "```zig" in response_text:
        start = response_text.find("```zig") + 6
        end = response_text.find("```", start)
        if end > start:
            return response_text[start:end].strip()
    if "```" in response_text:
        start = response_text.find("```") + 3
        if response_text[start:start + 1] == "\n":
            start += 1
        end = response_text.find("```", start)
        if end > start:
            return response_text[start:end].strip()
    return response_text.strip()


def get_all_python_files(directory):
    python_files = []
    for root, dirs, files in os.walk(directory):
        dirs[:] = [
            d for d in dirs if not d.startswith(".") and d != "__pycache__"
        ]
        for file in files:
            if file.endswith(".py"):
                python_files.append(os.path.join(root, file))
    return sorted(python_files)


async def transpile_file_async(session, python_file_path, output_base_dir,
                               source_base_dir, api_key, region, model_id,
                               semaphore, counter, total):
    async with semaphore:
        rel_path = os.path.relpath(python_file_path, source_base_dir)
        zig_rel_path = rel_path[:-3] + ".zig"
        zig_file_path = os.path.join(output_base_dir, zig_rel_path)

        try:
            with open(python_file_path, "r", encoding="utf-8") as f:
                python_code = f.read()
        except Exception as e:
            counter[0] += 1
            print(f"[{counter[0]}/{total}] ERROR read {rel_path}")
            return {"ok": False, "file": python_file_path, "error": str(e)}

        if not python_code.strip():
            os.makedirs(os.path.dirname(zig_file_path), exist_ok=True)
            with open(zig_file_path, "w", encoding="utf-8") as f:
                f.write("")
            counter[0] += 1
            print(f"[{counter[0]}/{total}] SKIP {rel_path}")
            return {
                "ok": True,
                "file": python_file_path,
                "zig_file": zig_file_path,
                "skipped": True
            }

        messages = [{"role": "user", "content": python_code}]

        result = await invoke_bedrock_async(session=session,
                                            messages=messages,
                                            system=TRANSPILE_SYSTEM_PROMPT,
                                            max_tokens=64000,
                                            temperature=0.0,
                                            region=region,
                                            model_id=model_id,
                                            api_key=api_key)

        if not result.get("ok"):
            counter[0] += 1
            print(f"[{counter[0]}/{total}] FAIL {rel_path}")
            return {
                "ok": False,
                "file": python_file_path,
                "error": result.get("error")
            }

        data = result.get("data")
        zig_code = ""
        if isinstance(data, dict):
            content_value = data.get("content")
            if isinstance(content_value, list):
                parts = []
                for item in content_value:
                    if isinstance(item, dict) and item.get(
                            "type") == "text" and isinstance(
                                item.get("text"), str):
                        parts.append(item["text"])
                zig_code = "".join(parts)
            if not zig_code and isinstance(data.get("raw"), str):
                zig_code = data["raw"]
        else:
            zig_code = str(data)

        zig_code = extract_zig_code(zig_code)

        os.makedirs(os.path.dirname(zig_file_path), exist_ok=True)

        try:
            with open(zig_file_path, "w", encoding="utf-8") as f:
                f.write(zig_code)
        except Exception as e:
            counter[0] += 1
            print(f"[{counter[0]}/{total}] FAIL write {rel_path}")
            return {"ok": False, "file": python_file_path, "error": str(e)}

        counter[0] += 1
        print(
            f"[{counter[0]}/{total}] OK {zig_rel_path} ({len(zig_code)})")
        return {
            "ok": True,
            "file": python_file_path,
            "zig_file": zig_file_path,
            "length": len(zig_code)
        }


async def run_transpilation_async():
    api_key = os.environ.get("AWS_BEARER_TOKEN_BEDROCK", "").strip()
    if not api_key:
        print("ERROR: AWS_BEARER_TOKEN_BEDROCK not set")
        return

    region = os.environ.get("AWS_REGION", "us-east-1")
    model_id = os.environ.get(
        "BEDROCK_MODEL_ID", "global.anthropic.claude-opus-4-5-20251101-v1:0")

    source_dir = os.path.join(os.getcwd(), "fajlok_core")
    output_dir = os.path.join(os.getcwd(), "fajlok_zig")

    if not os.path.isdir(source_dir):
        print("ERROR: fajlok_core not found")
        return

    os.makedirs(output_dir, exist_ok=True)

    python_files = get_all_python_files(source_dir)
    total = len(python_files)

    print(f"Transpiling {total} files (concurrency={CONCURRENCY})...")

    semaphore = asyncio.Semaphore(CONCURRENCY)
    counter = [0]

    connector = aiohttp.TCPConnector(limit=CONCURRENCY * 2,
                                     limit_per_host=CONCURRENCY * 2)
    async with aiohttp.ClientSession(connector=connector) as session:
        tasks = [
            transpile_file_async(session, py_file, output_dir, source_dir,
                                 api_key, region, model_id, semaphore, counter,
                                 total) for py_file in python_files
        ]
        results = await asyncio.gather(*tasks, return_exceptions=True)

    success = sum(1 for r in results if isinstance(r, dict) and r.get("ok"))
    errors = total - success

    print(f"Done! {success} OK, {errors} failed")


if __name__ == "__main__":
    print("fajlok Python→zig Transpiler")
    asyncio.run(run_transpilation_async())

