DEFAULT_USE_PREFIX = os.environ.get("BEDROCK_USE_PREFIX", "0").strip() == "1"
DEFAULT_TEMPERATURE = float(os.environ.get("TEMPERATURE", "0.0").strip() or "0.0")
DEFAULT_MAX_INPUT_CHARS = int(os.environ.get("MAX_INPUT_CHARS", "0").strip() or "0")
DEFAULT_OUTPUT_APPEND_OVERLAP_MAX = int(os.environ.get("OUTPUT_APPEND_OVERLAP_MAX", "8192").strip() or "8192")
DEFAULT_VERBOSE = os.environ.get("VERBOSE", "1").strip() != "0"

def _safe_int(value: Any, default: int) -> int:
    try:
        return int(value)
    except Exception:
        return default

def _safe_float(value: Any, default: float) -> float:
    try:
        return float(value)
    except Exception:
        return default

def normalize_messages(messages: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    normalized: List[Dict[str, Any]] = []
    for message in messages:
        role = str(message.get("role", "user")).strip() or "user"
        content = message.get("content", "")
        if isinstance(content, str):
            normalized.append({"role": role, "content": [{"type": "text", "text": content}]})
        elif isinstance(content, list):
            parts: List[Dict[str, str]] = []
            for item in content:
                if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                    parts.append({"type": "text", "text": item["text"]})
                elif isinstance(item, str):
                    parts.append({"type": "text", "text": item})
            if not parts:
                parts.append({"type": "text", "text": ""})
            normalized.append({"role": role, "content": parts})
        else:
            normalized.append({"role": role, "content": [{"type": "text", "text": str(content)}]})
    return normalized

def strip_code_fences(text: str) -> str:
    t = text.strip()
    if t.startswith("```"):
        first_nl = t.find("\n")
        if first_nl != -1:
            t = t[first_nl + 1 :]
        t = t.strip()
        if t.endswith("```"):
            t = t[:-3].rstrip()
    if t.startswith("```zig"):
        t = t[6:].lstrip("\n").strip()
        if t.endswith("```"):
            t = t[:-3].rstrip()
    return t.strip()

def extract_text_from_bedrock_response(data: Any) -> Tuple[str, Optional[str]]:
    if isinstance(data, dict):
        stop_reason = data.get("stop_reason") if isinstance(data.get("stop_reason"), str) else None
        content_value = data.get("content")
        if isinstance(content_value, list):
            parts: List[str] = []
            for item in content_value:
                if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                    parts.append(item["text"])
            return ("".join(parts), stop_reason)
        raw = data.get("raw")
        if isinstance(raw, str):
            return (raw, stop_reason)
        return (json.dumps(data, ensure_ascii=False), stop_reason)
    return (str(data), None)

def compute_prefix_suffix_overlap(existing: str, addition: str, max_len: int) -> int:
    if not existing or not addition:
        return 0
    max_check = min(len(existing), len(addition), max_len)
    for l in range(max_check, 0, -1):
        if existing[-l:] == addition[:l]:
            return l
    return 0

class FixedIntervalRateLimiter:
    def __init__(self, min_interval_seconds: float):
        self.min_interval_seconds = max(0.0, float(min_interval_seconds))
        self._lock = asyncio.Lock()
        self._next_time = 0.0

    async def acquire(self) -> None:
        if self.min_interval_seconds <= 0:
            return
        loop = asyncio.get_running_loop()
        now = loop.time()
        async with self._lock:
            scheduled = self._next_time if self._next_time > now else now
            self._next_time = scheduled + self.min_interval_seconds
        delay = scheduled - now
        if delay > 0:
            await asyncio.sleep(delay)

def build_model_id(model_id: str, use_prefix: bool, prefix: str) -> str:
    mid = (model_id or "").strip()
    if not mid:
        mid = "anthropic.claude-opus-4-6-v1"
    if use_prefix and prefix:
        pref = prefix.strip()
        if pref and not pref.endswith("."):
            pref = pref + "."
        if not mid.startswith(pref):
            mid = pref + mid
    return mid

async def invoke_bedrock_async(
    session: aiohttp.ClientSession,
    messages: List[Dict[str, Any]],
    system: Optional[str],
    max_tokens: int,
    temperature: Optional[float],
    region: str,
    model_id: str,
    api_key: str,
    rate_limiter: Optional[FixedIntervalRateLimiter],
    total_timeout_seconds: float,
    max_retries: int,
    base_delay: float
) -> Dict[str, Any]:
    if not api_key:
        return {"ok": False, "error": {"message": "Missing AWS_BEARER_TOKEN_BEDROCK"}}

    if rate_limiter is not None:
        await rate_limiter.acquire()

    url = f""

    body: Dict[str, Any] = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": int(max_tokens),
        "messages": normalize_messages(messages),
    }
    if system:
        body["system"] = system
    if temperature is not None:
        body["temperature"] = float(temperature)

    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json",
        "Authorization": f"Bearer {api_key}",
        "x-amz-bedrock-api-version": "2023-10-01",
    }

    timeout = aiohttp.ClientTimeout(total=total_timeout_seconds)
    last_error: Optional[Dict[str, Any]] = None

    for attempt in range(max_retries):
        try:
            async with session.post(url, json=body, headers=headers, timeout=timeout) as response:
                status = response.status
                raw_bytes = await response.read()
                retry_after = response.headers.get("Retry-After")
                if status == 429:
                    wait_s: Optional[float] = None
                    if retry_after is not None:
                        try:
                            wait_s = float(retry_after)
                        except Exception:
                            wait_s = None
                    if wait_s is None:
                        wait_s = base_delay * (attempt + 1)
                    if attempt < max_retries - 1:
                        await asyncio.sleep(max(0.0, wait_s))
                        continue
                    try:
                        error_body = json.loads(raw_bytes.decode("utf-8"))
                    except Exception:
                        error_body = {"message": raw_bytes.decode("utf-8", errors="ignore")}
                    return {"ok": False, "status": status, "error": error_body}

                if status >= 500:
                    if attempt < max_retries - 1:
                        await asyncio.sleep(base_delay * (attempt + 1))
                        continue
                    try:
                        error_body = json.loads(raw_bytes.decode("utf-8"))
                    except Exception:
                        error_body = {"message": raw_bytes.decode("utf-8", errors="ignore")}
                    return {"ok": False, "status": status, "error": error_body}

                if status != 200:
                    try:
                        error_body = json.loads(raw_bytes.decode("utf-8"))
                    except Exception:
                        error_body = {"message": raw_bytes.decode("utf-8", errors="ignore")}
                    return {"ok": False, "status": status, "error": error_body}

                try:
                    parsed = json.loads(raw_bytes.decode("utf-8"))
                    return {"ok": True, "data": parsed}
                except Exception:
                    return {"ok": True, "data": {"raw": raw_bytes.decode("utf-8", errors="ignore")}}
        except asyncio.TimeoutError:
            last_error = {"message": "Timeout"}
            if attempt < max_retries - 1:
                await asyncio.sleep(base_delay * (attempt + 1))
                continue
            return {"ok": False, "error": last_error}
        except Exception as e:
            last_error = {"message": str(e)}
            if attempt < max_retries - 1:
                await asyncio.sleep(base_delay * (attempt + 1))
                continue
            return {"ok": False, "error": last_error}

    return {"ok": False, "error": last_error or {"message": "Max retries exceeded"}}

def get_all_python_files(directory: str) -> List[str]:
    python_files: List[str] = []
    for root, dirs, files in os.walk(directory):
        dirs[:] = [d for d in dirs if not d.startswith(".") and d != "__pycache__"]
        for file in files:
            if file.endswith(".py"):
                python_files.append(os.path.join(root, file))
    return sorted(python_files)

async def transpile_file_async(
    session: aiohttp.ClientSession,
    python_file_path: str,
    output_base_dir: str,
    source_base_dir: str,
    api_key: str,
    region: str,
    model_id: str,
    semaphore: asyncio.Semaphore,
    counter: List[int],
    total: int,
    rate_limiter: Optional[FixedIntervalRateLimiter],
    max_output_tokens: int,
    max_continuations: int,
    temperature: float,
    total_timeout_seconds: float,
    max_retries: int,
    base_delay: float,
    max_input_chars: int,
    output_append_overlap_max: int,
    verbose: bool
) -> Dict[str, Any]:
    async with semaphore:
        rel_path = os.path.relpath(python_file_path, source_base_dir)
        zig_rel_path = rel_path[:-3] + ".zig"
        zig_file_path = os.path.join(output_base_dir, zig_rel_path)

        try:
            with open(python_file_path, "r", encoding="utf-8") as f:
                python_code = f.read()
        except Exception as e:
            counter[0] += 1
            if verbose:
                print(f"[{counter[0]}/{total}] ERROR read {rel_path}")
            return {"ok": False, "file": python_file_path, "error": str(e)}

        if not python_code.strip():
            os.makedirs(os.path.dirname(zig_file_path), exist_ok=True)
            try:
                with open(zig_file_path, "w", encoding="utf-8") as f:
                    f.write("")
            except Exception as e:
                counter[0] += 1
                if verbose:
                    print(f"[{counter[0]}/{total}] FAIL write {rel_path}")
                return {"ok": False, "file": python_file_path, "error": str(e)}
            counter[0] += 1
            if verbose:
                print(f"[{counter[0]}/{total}] SKIP {rel_path}")
            return {"ok": True, "file": python_file_path, "zig_file": zig_file_path, "skipped": True}

        if max_input_chars > 0 and len(python_code) > max_input_chars:
            counter[0] += 1
            if verbose:
                print(f"[{counter[0]}/{total}] FAIL {rel_path} input too large ({len(python_code)} > {max_input_chars})")
            return {"ok": False, "file": python_file_path, "error": f"Input too large ({len(python_code)} chars), MAX_INPUT_CHARS={max_input_chars}"}

        os.makedirs(os.path.dirname(zig_file_path), exist_ok=True)

        zig_accum = ""
        stop_reason: Optional[str] = None

        messages: List[Dict[str, Any]] = [{"role": "user", "content": python_code}]

        for step in range(max_continuations + 1):
            result = await invoke_bedrock_async(
                session=session,
                messages=messages,
                system=TRANSPILE_SYSTEM_PROMPT,
                max_tokens=max_output_tokens,
                temperature=temperature,
                region=region,
                model_id=model_id,
                api_key=api_key,
                rate_limiter=rate_limiter,
                total_timeout_seconds=total_timeout_seconds,
                max_retries=max_retries,
                base_delay=base_delay
            )

            if not result.get("ok"):
                counter[0] += 1
                if verbose:
                    print(f"[{counter[0]}/{total}] FAIL {rel_path}")
                return {"ok": False, "file": python_file_path, "error": result.get("error")}

            data = result.get("data")
            chunk_text, stop_reason = extract_text_from_bedrock_response(data)
            chunk_text = strip_code_fences(chunk_text)

            if chunk_text:
                overlap = compute_prefix_suffix_overlap(zig_accum, chunk_text, output_append_overlap_max)
                if overlap > 0:
                    chunk_text = chunk_text[overlap:]
                zig_accum += chunk_text

            if stop_reason is None:
                break

            if stop_reason != "max_tokens":
                break

            if step >= max_continuations:
                break

            messages = [
                {"role": "user", "content": python_code},
                {"role": "assistant", "content": zig_accum},
                {"role": "user", "content": "Continue the Zig code exactly where you left off. Output ONLY the remaining Zig code. Do not repeat any already output text."}
            ]

        try:
            with open(zig_file_path, "w", encoding="utf-8") as f:
                f.write(zig_accum)
        except Exception as e:
            counter[0] += 1
            if verbose:
                print(f"[{counter[0]}/{total}] FAIL write {rel_path}")
            return {"ok": False, "file": python_file_path, "error": str(e)}

        counter[0] += 1
        if verbose:
            sr = stop_reason if stop_reason is not None else "unknown"
            print(f"[{counter[0]}/{total}] OK {zig_rel_path} ({len(zig_accum)} chars, stop_reason={sr})")
        return {"ok": True, "file": python_file_path, "zig_file": zig_file_path, "length": len(zig_accum), "stop_reason": stop_reason}

async def run_transpilation_async() -> None:
    api_key = os.environ.get("AWS_BEARER_TOKEN_BEDROCK", "").strip()
    if not api_key:
        print("ERROR: AWS_BEARER_TOKEN_BEDROCK not set")
        return

    concurrency = DEFAULT_CONCURRENCY if DEFAULT_CONCURRENCY > 0 else 1
    max_retries = DEFAULT_MAX_RETRIES if DEFAULT_MAX_RETRIES > 0 else 1
    base_delay = DEFAULT_BASE_DELAY if DEFAULT_BASE_DELAY >= 0 else 0.0
    max_output_tokens = DEFAULT_MAX_OUTPUT_TOKENS if DEFAULT_MAX_OUTPUT_TOKENS > 0 else 1024
    max_continuations = DEFAULT_MAX_CONTINUATIONS if DEFAULT_MAX_CONTINUATIONS >= 0 else 0
    temperature = DEFAULT_TEMPERATURE
    total_timeout_seconds = DEFAULT_TOTAL_TIMEOUT_SECONDS if DEFAULT_TOTAL_TIMEOUT_SECONDS > 0 else 600
    max_input_chars = DEFAULT_MAX_INPUT_CHARS if DEFAULT_MAX_INPUT_CHARS >= 0 else 0
    output_append_overlap_max = DEFAULT_OUTPUT_APPEND_OVERLAP_MAX if DEFAULT_OUTPUT_APPEND_OVERLAP_MAX > 0 else 8192
    verbose = DEFAULT_VERBOSE

    region = DEFAULT_REGION
    model_id_base = DEFAULT_MODEL_ID
    model_id = build_model_id(model_id_base, DEFAULT_USE_PREFIX, DEFAULT_MODEL_ID_PREFIX)

    rpm = DEFAULT_REQUESTS_PER_MINUTE if DEFAULT_REQUESTS_PER_MINUTE >= 0 else 0.0
    min_seconds_between = DEFAULT_MIN_SECONDS_BETWEEN_REQUESTS if DEFAULT_MIN_SECONDS_BETWEEN_REQUESTS >= 0 else 0.0
    if rpm > 0:
        min_seconds_between = max(min_seconds_between, 60.0 / rpm)

    rate_limiter: Optional[FixedIntervalRateLimiter] = None
    if min_seconds_between > 0:
        rate_limiter = FixedIntervalRateLimiter(min_seconds_between)

    source_dir = os.path.join(os.getcwd(), "fajlok_core")
    output_dir = os.path.join(os.getcwd(), "fajlok_zig")

    if not os.path.isdir(source_dir):
        print("ERROR: fajlok_core not found")
        return

    os.makedirs(output_dir, exist_ok=True)

    python_files = get_all_python_files(source_dir)
    total = len(python_files)

    if verbose:
        rl_info = f", min_interval={min_seconds_between:.4f}s" if rate_limiter is not None else ""
        print(f"Transpiling {total} files (concurrency={concurrency}, max_output_tokens={max_output_tokens}, max_continuations={max_continuations}{rl_info})...")

    semaphore = asyncio.Semaphore(concurrency)
    counter = [0]

    connector_limit = max(1, concurrency * max(1, DEFAULT_CONNECTOR_LIMIT_MULTIPLIER))
    connector = aiohttp.TCPConnector(limit=connector_limit, limit_per_host=connector_limit, ttl_dns_cache=300)

    async with aiohttp.ClientSession(connector=connector) as session:
        tasks = [
            transpile_file_async(
                session=session,
                python_file_path=py_file,
                output_base_dir=output_dir,
                source_base_dir=source_dir,
                api_key=api_key,
                region=region,
                model_id=model_id,
                semaphore=semaphore,
                counter=counter,
                total=total,
                rate_limiter=rate_limiter,
                max_output_tokens=max_output_tokens,
                max_continuations=max_continuations,
                temperature=temperature,
                total_timeout_seconds=total_timeout_seconds,
                max_retries=max_retries,
                base_delay=base_delay,
                max_input_chars=max_input_chars,
                output_append_overlap_max=output_append_overlap_max,
                verbose=verbose
            )
            for py_file in python_files
        ]
        results = await asyncio.gather(*tasks, return_exceptions=True)

    success = 0
    failures = 0
    exceptions = 0
    for r in results:
        if isinstance(r, dict):
            if r.get("ok"):
                success += 1
            else:
                failures += 1
        else:
            exceptions += 1

    if verbose:
        print(f"Done! {success} OK, {failures} failed, {exceptions} exceptions")

def main() -> None:
    print("fajlok Python→zig Transpiler")
    asyncio.run(run_transpilation_async())

if __name__ == "__main__":
    main()
